// Painel instalável no celular (PWA): manifesto, ícones e um service worker mínimo.
// - Android/Chrome: "Instalar app" aparece quando o painel abre por HTTPS (ex.: Tailscale com HTTPS ligado);
//   por http://IP o Chrome só cria um atalho, porque service worker exige contexto seguro.
// - iPhone/Safari: Compartilhar → "Adicionar à Tela de Início" abre em tela cheia mesmo por http.
// O service worker não guarda dados: sempre busca na rede e só mostra uma página "sem conexão" se a placa
// não responder (o painel é ao vivo, cache de dados velhos enganaria).
// Ícones gerados de umbrel/icon.svg (o mesmo do app do Umbrel).

const ICON_SVG = "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 256 256\">\n  <rect width=\"256\" height=\"256\" rx=\"56\" fill=\"#f2a900\"/>\n  <g fill=\"none\" stroke=\"#1a1408\" stroke-width=\"18\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n    <path d=\"M78 186 L170 94\"/>\n    <path d=\"M118 66 C150 62 184 74 202 104 C188 90 166 84 146 88\"/>\n    <path d=\"M118 66 C114 98 126 132 156 150 C142 136 136 114 140 94\"/>\n  </g>\n  <circle cx=\"186\" cy=\"188\" r=\"22\" fill=\"#1a1408\"/>\n  <text x=\"186\" y=\"196\" font-family=\"Arial, sans-serif\" font-size=\"24\" font-weight=\"700\" fill=\"#f2a900\" text-anchor=\"middle\">\u20bf</text>\n</svg>\n";
const PNG = {"icon-192.png": "", "icon-512.png": "", "maskable-512.png": "", "apple-touch-icon.png": ""};

// cor da barra do sistema = fundo de cada tema
const THEME_BG = { obsidian: '#0e1117', ocean: '#0b111e', neon: '#0a111b', gold: '#0b0e11', latte: '#f5f3ee' };

function manifest({ lang = 'pt', theme = 'obsidian', title } = {}) {
  const pt = lang !== 'en';
  const bg = THEME_BG[theme] || THEME_BG.obsidian;
  return {
    name: title || (pt ? 'Fazenda de Mineração' : 'Mining farm'),
    short_name: 'HomeMiner',
    description: pt ? 'Painel da fazenda de mineração de bitcoin (HomeMinerProxy)' : 'Bitcoin mining farm dashboard (HomeMinerProxy)',
    lang: pt ? 'pt-BR' : 'en',
    id: '/',
    start_url: '/',
    scope: '/',
    display: 'standalone',
    orientation: 'any',
    background_color: bg,
    theme_color: bg,
    icons: [
      { src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: '/icons/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: '/icons/maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
      { src: '/icons/icon.svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any' },
    ],
  };
}

function offlinePage(lang) {
  const pt = lang !== 'en';
  return '<!doctype html><html lang="' + (pt ? 'pt-BR' : 'en') + '"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<title>HomeMiner</title><body style="margin:0;min-height:100vh;display:grid;place-items:center;background:#0d1117;color:#e6edf3;font-family:system-ui,sans-serif;text-align:center;padding:24px">' +
    '<div><div style="font-size:48px">⛏️</div><h1 style="font-size:20px">' + (pt ? 'Sem conexão com a fazenda' : 'Can\'t reach the farm') + '</h1>' +
    '<p style="color:#8b949e">' + (pt ? 'O painel só abre na rede de casa (ou pelo Tailscale). Confira o Wi-Fi e tente de novo.' : 'The dashboard only opens on your home network (or over Tailscale). Check the Wi-Fi and try again.') + '</p>' +
    '<button onclick="location.reload()" style="margin-top:8px;padding:10px 18px;border-radius:8px;border:0;background:#f2a900;color:#1a1408;font-weight:600">' + (pt ? 'Tentar de novo' : 'Try again') + '</button></div></body></html>';
}

function serviceWorker(lang) {
  return `// HomeMinerProxy: service worker mínimo (rede primeiro; sem dados em cache)
const OFFLINE = ${JSON.stringify(offlinePage(lang))};
self.addEventListener('install', () => self.skipWaiting());
self.addEventListener('activate', (e) => e.waitUntil(self.clients.claim()));
self.addEventListener('fetch', (e) => {
  if (e.request.mode !== 'navigate') return;   // API e o resto: direto na rede, como sempre
  e.respondWith(fetch(e.request).catch(() => new Response(OFFLINE, { headers: { 'Content-Type': 'text/html; charset=utf-8' } })));
});
`;
}

// Responde as rotas do PWA; devolve true se respondeu
function handle(req, res, opts = {}) {
  const url = req.url.split('?')[0];
  const send = (code, type, body, cache) => { res.writeHead(code, { 'Content-Type': type, 'Cache-Control': cache || 'no-cache' }); res.end(body); };
  if (url === '/manifest.webmanifest') { send(200, 'application/manifest+json; charset=utf-8', JSON.stringify(manifest(opts))); return true; }
  if (url === '/sw.js') { res.setHeader('Service-Worker-Allowed', '/'); send(200, 'text/javascript; charset=utf-8', serviceWorker(opts.lang)); return true; }
  if (url === '/icons/icon.svg' || url === '/favicon.svg') { send(200, 'image/svg+xml', ICON_SVG, 'public, max-age=86400'); return true; }
  const m = /^\/(?:icons\/)?([a-z0-9-]+\.png)$/.exec(url);
  if (m && PNG[m[1]]) { send(200, 'image/png', Buffer.from(PNG[m[1]], 'base64'), 'public, max-age=86400'); return true; }
  if (url === '/favicon.ico') { send(200, 'image/png', Buffer.from(PNG['icon-192.png'], 'base64'), 'public, max-age=86400'); return true; }
  return false;
}

// Tags do <head> do painel
function headTags(theme = 'obsidian') {
  const bg = THEME_BG[theme] || THEME_BG.obsidian;
  return '<link rel="manifest" href="/manifest.webmanifest">\n<meta name="theme-color" content="' + bg + '">\n' +
    '<link rel="icon" type="image/svg+xml" href="/favicon.svg">\n<link rel="apple-touch-icon" href="/apple-touch-icon.png">\n' +
    '<meta name="apple-mobile-web-app-capable" content="yes">\n<meta name="mobile-web-app-capable" content="yes">\n' +
    '<meta name="apple-mobile-web-app-status-bar-style" content="black">\n<meta name="apple-mobile-web-app-title" content="HomeMiner">';
}

module.exports = { manifest, serviceWorker, offlinePage, handle, headTags, THEME_BG, PNG };
